/**
 * FILE 4 — core/scaleTable.ts
 *
 * The 18 Lucas-stable scale records, generated BY FORMULA from constants — never
 * hand-typed (spec §3/File 4). Plus the full 43-rung continuation for coarse-graining.
 * Permanently replaces the discredited source ladder (L(292)=10⁴⁰ error).
 *
 * Fields per record (spec §2), all in Scaled (arbitrary-magnitude) form:
 *   L      = ℓ_P·φⁿ            [m]   length of the rung
 *   T      = t_P·φⁿ            [s]   base time
 *   tau    = T·(1+0.01·n)      [s]   golden-delay-shifted time
 *   deltaX = L                 [m]   spatial resolution of the rung (= L by convention)
 *   rhoI   = ℓ_P⁻³·φ⁻ⁿ         [m⁻³] information density (ρ₀·φ⁻ⁿ)
 *   vWave  = c·φ⁻ⁿᐟ²           [m/s] canonical ladder wave-speed (B2: medium form OPEN)
 *   complexityBits = 2.0783·n        dimensionless
 *   winding  = round(φⁿ/13)          BigInt (Metatron winding number)
 *   lucasResidue = min(Lₙ mod 13, 13−·) = 1 for all stable n
 *   isMetatronShell ⇔ n = 13
 */

import {
  PHI,
  PLANCK_LENGTH,
  PLANCK_TIME,
  C,
  GOLDEN_DELAY_EPS,
  METATRON_SHELL,
  STABLE_SCALES,
  type StableScaleIndex,
} from "./constants.ts";
import { Scaled } from "./provenance.ts";
import { closureResidueMin, stableScalesUpTo, lucas } from "./lucas.ts";

/** A fully-computed, immutable stable-scale record. */
export interface ScaleRecord {
  readonly n: number;
  readonly L: Scaled;
  readonly T: Scaled;
  readonly tau: Scaled;
  readonly deltaX: Scaled;
  readonly rhoI: Scaled;
  readonly vWave: Scaled;
  readonly complexityBits: number;
  readonly nNodes: Scaled;
  readonly winding: bigint;
  readonly lucasResidue: number;
  readonly stable: true;
  readonly isMetatronShell: boolean;
}

/** Complexity-bits coefficient C_bits = 2.0783·n (spec §2). */
const COMPLEXITY_COEFF = 2.0783;

/** Build one scale record by formula. */
function buildRecord(n: number): ScaleRecord {
  const phiN = Scaled.phiPow(n, PHI); // φⁿ
  const phiNegN = Scaled.phiPow(-n, PHI); // φ⁻ⁿ
  const phiNegNhalf = Scaled.phiPow(-n / 2, PHI); // φ⁻ⁿᐟ²

  const L = Scaled.from(PLANCK_LENGTH).mul(phiN);
  const T = Scaled.from(PLANCK_TIME).mul(phiN);
  const tau = T.mul(Scaled.from(1 + GOLDEN_DELAY_EPS * n));
  const rhoI = Scaled.from(PLANCK_LENGTH).pow(-3).mul(phiNegN);
  const vWave = Scaled.from(C).mul(phiNegNhalf);
  const complexityBits = COMPLEXITY_COEFF * n;
  // nNodes ∝ surface count on the rung's torus; parameterized as φⁿ/φ = φⁿ⁻¹ (Scaled).
  const nNodes = Scaled.phiPow(n - 1, PHI);
  // W = round(φⁿ/13). φⁿ is irrational, so compute EXACTLY via the Lucas integer:
  // φⁿ = Lₙ + (−1)ⁿ⁺¹φ⁻ⁿ, and φ⁻ⁿ < 6.5 for n ≥ 4, so round(φⁿ/13) = round(Lₙ/13).
  const L13 = lucas(n) % 13n; // exact integer residue
  const winding = lucas(n) / 13n + (L13 * 2n >= 13n ? 1n : 0n); // round half up on Lₙ/13

  return Object.freeze({
    n,
    L,
    T,
    tau,
    deltaX: L,
    rhoI,
    vWave,
    complexityBits,
    nNodes,
    winding,
    lucasResidue: closureResidueMin(n),
    stable: true as const,
    isMetatronShell: n === METATRON_SHELL,
  });
}

// Lazily-built, memoized table keyed by n — generated once, immutable.
const TABLE = new Map<number, ScaleRecord>();
for (const n of stableScalesUpTo(293)) TABLE.set(n, buildRecord(n));

/** Get the record for any stable rung (dense core or continuation). Throws if n not stable. */
export function getScale(n: number): ScaleRecord {
  const rec = TABLE.get(n);
  if (!rec) throw new RangeError(`getScale: n=${n} is not a Lucas-stable scale`);
  return rec;
}

/** The 18 dense-core stable records, ascending n. */
export function allScales(): readonly ScaleRecord[] {
  return STABLE_SCALES.map((n) => getScale(n));
}

/** The 25 continuation rungs (19–43) for coarse-graining, ascending n. */
export const CONTINUATION: readonly ScaleRecord[] = stableScalesUpTo(293)
  .filter((n) => !(STABLE_SCALES as readonly number[]).includes(n))
  .map((n) => getScale(n));

/** Convenience: the 18 stable indices (re-export for downstream files). */
export const DENSE_CORE_N: readonly StableScaleIndex[] = STABLE_SCALES;
